[ExtensionOf(formDataSourceStr(TSTimesheetEntryFormPart, TSTimesheetEntryTotalsPart))]
public final class AVATSTimehseetEntryFormPart_TSTimesheetEntryTotalsPartFds_Extension
{
}

Method.Source:
/// <summary>
/// displays all hours booked for selected timeframe and user
/// </summary>
/// <returns>AVAHoursBooked</returns>
public display AVAHoursBooked avaDisplayHoursBooked()
{
    AVAHoursBooked avaHours;
    TSTimesheetLineWeek         avaTSTimesheetLineWeek;
    TSTimesheetTable            avaTSTimesheetTable;

    TSTimesheetEntryTotalsPart  locTotalsPart = this.cursor();
    //TSTimesheetTable            locTSTimesheetTable = TSTimesheetTable::findRecId(locTotalsPart.RecId);

    while select avaTSTimesheetLineWeek
        join avaTSTimesheetTable
        where avaTSTimesheetLineWeek.TimesheetNbr           == avaTSTimesheetTable.TimesheetNbr
            && avaTSTimesheetTable.ProjPeriodTimesheetWeek  == locTotalsPart.ProjPeriodTimesheetWeek
            && avaTSTimesheetTable.Resource                 == locTotalsPart.Resource
            && (avaTSTimesheetTable.PostStatus              == TSPostStatus::Posted
                || avaTSTimesheetTable.PostStatus           == TSPostStatus::Transferred)
    {
        avaHours += avaTSTimesheetLineWeek.Hours[1]
            + avaTSTimesheetLineWeek.Hours[2]
            + avaTSTimesheetLineWeek.Hours[3]
            + avaTSTimesheetLineWeek.Hours[4]
            + avaTSTimesheetLineWeek.Hours[5]
            + avaTSTimesheetLineWeek.Hours[6]
            + avaTSTimesheetLineWeek.Hours[7];
    }

    return avaHours;
}

/// <summary>
/// displays all hours unbooked for selected timeframe and user
/// </summary>
/// <returns>AVAHoursUnbooked</returns>
public display AVAHoursUnbooked avaDisplayHoursUnbooked()
{
    AVAHoursUnBooked avaHours;
    TSTimesheetLineWeek         avaTSTimesheetLineWeek;
    TSTimesheetTable            avaTSTimesheetTable;

    TSTimesheetEntryTotalsPart  locTotalsPart = this.cursor();
    //TSTimesheetTable            locTSTimesheetTable = TSTimesheetTable::findRecId(locTotalsPart.RecId);

    while select avaTSTimesheetLineWeek
        join avaTSTimesheetTable
        where avaTSTimesheetLineWeek.TimesheetNbr           == avaTSTimesheetTable.TimesheetNbr
            && avaTSTimesheetTable.ProjPeriodTimesheetWeek  == locTotalsPart.ProjPeriodTimesheetWeek
            && avaTSTimesheetTable.Resource                 == locTotalsPart.Resource
            && avaTSTimesheetTable.PostStatus               == TSPostStatus::NotTransferred
    {
        avaHours += avaTSTimesheetLineWeek.Hours[1]
            + avaTSTimesheetLineWeek.Hours[2]
            + avaTSTimesheetLineWeek.Hours[3]
            + avaTSTimesheetLineWeek.Hours[4]
            + avaTSTimesheetLineWeek.Hours[5]
            + avaTSTimesheetLineWeek.Hours[6]
            + avaTSTimesheetLineWeek.Hours[7];
    }

    return avaHours;
}

/// <summary>
/// displays the sum of all hours for selected timeframe and user
/// </summary>
/// <returns>AVAHoursTotal</returns>
public display AVAHoursTotal avaDisplayHoursTotal()
{
    AVAHoursTotal avaHours;

    avaHours = this.avaDisplayHoursBooked() + this.avaDisplayHoursUnbooked();

    return avaHours;
}
